import * as THREE from "three";
import { OrbitControls } from "three-orbitcontrols-ts";
import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader";

import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/examples/jsm/postprocessing/UnrealBloomPass.js";
import { SSAOPass } from "three/examples/jsm/postprocessing/SSAOPass.js";

import { getDirectionalLight } from "../threeFn";

const createStudioEnvironment = (scene) => {
  const geometry = new THREE.SphereGeometry(1000, 32, 16);
  const material = new THREE.ShaderMaterial({
    uniforms: {
      topColor: { value: new THREE.Color(0xffffff) },
      bottomColor: { value: new THREE.Color(0xefefef) },
      offset: { value: 0.6 },
      exponent: { value: 0.8 },
    },
    vertexShader: `
                    varying vec3 vWorldPosition;
                    void main() {
                        vec4 worldPosition = modelMatrix * vec4(position, 1.0);
                        vWorldPosition = worldPosition.xyz;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
    fragmentShader: `
                    uniform vec3 topColor;
                    uniform vec3 bottomColor;
                    uniform float offset;
                    uniform float exponent;
                    varying vec3 vWorldPosition;
                    void main() {
                        float h = normalize(vWorldPosition + offset).y;
                        gl_FragColor = vec4(mix(bottomColor, topColor, max(pow(max(h, 0.0), exponent), 0.0)), 1.0);
                    }
                `,
    side: THREE.BackSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  scene.add(mesh);

  return scene;
};

export class ThreeCore {
  canvas: HTMLCanvasElement;
  host: HTMLElement;
  ctx: CanvasRenderingContext2D;
  t: number = 0.0;
  camera: THREE.PerspectiveCamera;
  scene: THREE.Scene;
  renderer: THREE.WebGLRenderer;
  controls: OrbitControls;
  requestFrame: number;
  composer: EffectComposer;

  loaded = false;

  constructor(id: string) {
    this.initCanvas(id);
  }
  public initCanvas(id: string) {
    this.host = document.getElementById(id);

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0, 0, 0);
    this.scene.castShadow = true;

    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setPixelRatio(this.host.clientWidth / this.host.clientHeight);
    this.renderer.domElement.id = "Three";

    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // this.renderer.outputEncoding = THREE.sRGBEncoding
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
    this.host.appendChild(this.renderer.domElement);

    this.scene.background = new THREE.Color(0xffffff);
    getDirectionalLight(this.scene);

    // this.initLight()
    this.initHDRI();

    const planeGeometry = new THREE.PlaneGeometry(200, 200);
    const planeMaterial = new THREE.MeshStandardMaterial({
      color: 0xefefef,
      roughness: 0.8,
      metalness: 0.8,
    });

    const plane = new THREE.Mesh(planeGeometry, planeMaterial);
    plane.rotation.x = -Math.PI / 2;
    plane.receiveShadow = true;
    plane.position.y = -18;
    this.scene.add(plane);
  }
  initLight() {
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.55);
    ambientLight.castShadow = true;
    this.scene.add(ambientLight);

    let pointLight = new THREE.PointLight(0xffffff, 100);
    pointLight.position.x = 10;
    pointLight.castShadow = true;
    this.scene.add(pointLight);

    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // this.renderer.outputEncoding = THREE.sRGBEncoding;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    createStudioEnvironment(this.scene);

    this.init();
  }
  initHDRI() {
    const ambient = new THREE.AmbientLight(0x404040, 0.1); // 약한 배경 조명
    this.scene.add(ambient);

    const path =
      process.env.PUBLIC_URL + "/static/data/model/notebook_pano_full.hdr";
    const loader = new RGBELoader();
    loader.load(path, (texture) => {
      texture.mapping = THREE.EquirectangularReflectionMapping;
      this.scene.environment = texture;
      // this.scene.environment = this.scene.texture;
      this.scene.background = texture;

      // new RGBELoader()
      // .setPath('textures/') // 여기에 .hdr 파일이 위치
      // .load('studio_small_09_2k.hdr', (texture) => {
      //     texture.mapping = THREE.EquirectangularReflectionMapping
      //     scene.environment = texture
      //     scene.background = texture
      // })

      // function createHDRI() {
      //     // 프로시저럴 HDRI 환경맵 생성
      //     const pmremGenerator = new THREE.PMREMGenerator(renderer);
      //     const renderTarget = pmremGenerator.fromScene(createStudioEnvironment());
      //     envMap = renderTarget.texture;
      //     scene.environment = envMap;
      //     pmremGenerator.dispose();
      // }

      createStudioEnvironment(this.scene);

      this.renderer.shadowMap.enabled = true;
      this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

      //     mesh.castShadow = true;
      //     mesh.receiveShadow = true;
      this.init();
    });
  }
  init() {
    this.camera = new THREE.PerspectiveCamera(
      30,
      this.host.clientWidth / this.host.clientHeight,
      1,
      5000
    );
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.camera.position.set(0, 0, 150);
    this.controls.minPolarAngle = 0; // 위쪽 제한 (0: 위에서 내려다봄)
    this.controls.maxPolarAngle = Math.PI / 2; // 아래쪽 제한 (PI/2: 수평)
    this.controls.update();

    const composer = new EffectComposer(this.renderer);
    composer.addPass(new RenderPass(this.scene, this.camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.1,
      1.8,
      0.55
    );
    composer.addPass(bloomPass);

    // const composer = new EffectComposer(renderer);
    // composer.addPass(new RenderPass(scene, camera));

    const ssaoPass = new SSAOPass(
      this.scene,
      this.camera,
      window.innerWidth,
      window.innerHeight
    );
    ssaoPass.kernelRadius = 32;
    ssaoPass.minDistance = 0.1;
    ssaoPass.maxDistance = 20.05;
    ssaoPass.output = SSAOPass.OUTPUT.Default;

    // composer.addPass(ssaoPass);

    this.composer = composer;

    this.eventBind();
    this.loop();
  }
  eventBind() {
    this.renderer.domElement.onmousedown = (e: MouseEvent) => this.MouseDown(e);
    this.renderer.domElement.onmouseup = (e: MouseEvent) => this.MouseUp(e);
    this.renderer.domElement.onmousemove = (e: MouseEvent) => this.MouseMove(e);

    window.addEventListener("resize", () => this.onWindowResize());
    // this.host.addEventListener('resize', () => this.onWindowResize() );

    const onClick = (event) => {
      const raycaster = new THREE.Raycaster();
      const mouse = new THREE.Vector2();

      // 1) 마우스 좌표를 -1 ~ 1 사이 NDC 좌표로 변환
      mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

      // 2) Raycaster에 카메라와 마우스 위치를 설정
      raycaster.setFromCamera(mouse, this.camera);

      // 3) 씬에서 충돌 객체들 검사
      const intersects = raycaster.intersectObjects(
        this.scene.children,
        true
      );

      if (intersects.length > 0) {
        // 가장 가까운 객체 선택
        const selectedObject = intersects[0].object;
        console.log("Selected object:", selectedObject);

        // 예: 원하는 프로퍼티 출력
        console.log("Name:", selectedObject.name);
        console.log("position:", selectedObject.position);
        console.log("scale:", selectedObject.scale);
        console.log("Material:", selectedObject.material);
        // selectedObject.position.y += 100;
        // 필요하면 추가 처리 가능
      } else {
        // console.log("아무 오브젝트도 선택되지 않았습니다.");
      }
    }

    window.addEventListener("click", onClick, false);
  }
  private onWindowResize() {
    this.camera.aspect = this.host.clientWidth / this.host.clientHeight;
    this.camera.updateProjectionMatrix();

    this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
  }
  MouseDown(e: MouseEvent) {
    console.log(e);
    onClick(e);
  }
  MouseUp(e: MouseEvent) {
    console.log(e);
  }
  MouseMove(e: MouseEvent) {
    console.log(e);
  }
  loop = () => {
    this.requestFrame = requestAnimationFrame(this.loop);

    if (this.loaded) {
      this.controls.update();
      this.render();
      // this.renderer.render(this.scene, this.camera);
      this.composer.render();
      this.t += 0.01;
    }
  };
  render() {}
  destroy() {
    window.removeEventListener("resize", () => this.onWindowResize());
    cancelAnimationFrame(this.requestFrame);
    this.requestFrame = undefined;
    while (this.host.lastChild) {
      this.host.removeChild(this.host.lastChild);
    }
  }
}
